{
  "query": "query GetMenuItem($itemId: UUID!) { getMenuItemById(itemId: $itemId) { itemId restaurantId itemName itemDescription itemImage itemPrice discountedPrice isVeg isAvailable preparationTime itemImgUrl category { categoryId categoryName } } }",
  "variables": { "itemId": "{{itemId}}" }
}

{
  "query": "query GetMenuItems($restaurantId: UUID!) { getMenuItems(restaurantId: $restaurantId) { itemId itemName itemPrice isVeg isAvailable category { categoryId categoryName } } }",
  "variables": { "restaurantId": "{{restaurantId}}" }
}

{
  "query": "query GetMenuCategories($restaurantId: UUID!) { getMenuCategories(restaurantId: $restaurantId) { categoryId categoryName categoryDescription restaurantId isActive menuItemList { itemId itemName itemPrice } } }",
  "variables": { "restaurantId": "{{restaurantId}}" }
}

{
  "query": "query GetMenuCategory($categoryId: UUID!) { getMenuCategory(categoryId: $categoryId) { categoryId categoryName categoryDescription restaurantId isActive } }",
  "variables": { "categoryId": "{{categoryId}}" }
}

{
  "query": "query { restaurants { restaurantId name description phoneNumber email addressLine1 city state country postalCode latitude longitude rating ratingCount priceForTwo deliveryMinTime deliveryMaxTime isPureVeg isActive restaurantHours { restaurantHoursId dayOfWeek openingTime closingTime isClosed } } }"
}

{
  "query": "query GetRestaurant($id: UUID!) { restaurant(id: $id) { restaurantId name description rating isActive cuisines { cuisineId name slug } } }",
  "variables": { "id": "{{restaurantId}}" }
}

{
  "query": "query { cuisines { cuisineId name slug imageUrl isActive } }"
}

{
  "query": "query GetCuisine($id: UUID!) { cuisine(id: $id) { cuisineId name slug imageUrl isActive } }",
  "variables": { "id": "{{cuisineId}}" }
}

{
  "query": "query CartByUser($userId: UUID!) { cartByUserId(userId: $userId) { cartId userId restaurantId status cartItems { cartItemId menuItemId itemName unitPrice quantity totalPrice } } }",
  "variables": { "userId": "{{userId}}" }
}

{
  "query": "query CartItems($cartId: UUID!) { cartItemsByCartId(cartId: $cartId) { cartItemId menuItemId itemName unitPrice quantity totalPrice } }",
  "variables": { "cartId": "{{cartId}}" }
}

{
  "query": "query Favourites($userId: ID!) { favouritesByUserId(userId: $userId) { id userId restaurantId createdAt } }",
  "variables": { "userId": "{{userId}}" }
}

{
  "query": "query Favourite($id: UUID!) { favourite(id: $id) { id userId restaurantId createdAt } }",
  "variables": { "id": "{{restaurantId}}" }
}

{
  "query": "query Orders($userId: ID!) { getAllOrders(userId: $userId) { orderId orderNumber userId restaurantId deliveryAddressId status paymentStatus subtotal deliveryFee discount total orderItems { orderItemId menuItemId itemName unitPrice quantity totalPrice } } }",
  "variables": { "userId": "{{userId}}" }
}

{
  "query": "query Order($orderId: ID!) { getOrderByOrderId(orderId: $orderId) { orderId orderNumber status paymentStatus total cancelReason } }",
  "variables": { "orderId": "{{orderId}}" }
}

{
  "query": "query StatusHistory($orderId: ID!) { getStatusHistoryByOrderId(orderId: $orderId) { id orderId status createdAt } }",
  "variables": { "orderId": "{{orderId}}" }
}

{
  "query": "query Payment($paymentId: UUID!) { findPaymentByPaymentId(paymentId: $paymentId) { paymentId orderId amount userId currency method status provider transactionId } }",
  "variables": { "paymentId": "{{paymentId}}" }
}

{
  "query": "query PaymentByTransaction($transactionId: UUID!) { findPaymentByTransactionId(transactionId: $transactionId) { paymentId orderId amount currency method status transactionId } }",
  "variables": { "transactionId": "{{transactionId}}" }
}

{
  "query": "query Payments($userId: UUID!) { getAllPaymentsByUserId(userId: $userId) { paymentId orderId amount currency method status provider transactionId } }",
  "variables": { "userId": "{{userId}}" }
}
